import { useCallback, useRef, useState } from 'react';
import { JxButton, JxModal } from '@jinx-ui/react';

type DeleteProjectProps = {
  onConfirm: () => void;
};

export default function DeleteProject({ onConfirm }: DeleteProjectProps) {
  const [confirmOpen, setConfirmOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  const changeOpen = useCallback((open: boolean) => {
    setConfirmOpen(open);
    if (!open) triggerRef.current?.focus();
  }, []);

  const confirm = useCallback(() => {
    changeOpen(false);
    onConfirm();
  }, [changeOpen, onConfirm]);

  return (
    <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
      <JxButton
        ref={triggerRef}
        variant="danger"
        onClick={() => setConfirmOpen(true)}
      >
        Удалить проект
      </JxButton>

      <JxModal
        open={confirmOpen}
        onOpenChange={changeOpen}
        intent="danger"
        title="Удалить проект?"
        message="Действие необратимо: проект и все его задачи будут удалены безвозвратно."
      >
        <JxButton variant="ghost" onClick={() => changeOpen(false)}>
          Отмена
        </JxButton>
        <JxButton variant="danger" onClick={confirm}>
          Удалить
        </JxButton>
      </JxModal>
    </div>
  );
}

